import { once } from "node:events";
import { createServer } from "node:http";

export function serve(handler, { port = 8787, host = "127.0.0.1", log } = {}) {
  const server = createServer(async (req, res) => {
    const started = Date.now();
    let status = 500;
    let rpc = "";
    try {
      const headers = new Headers();
      for (const [name, value] of Object.entries(req.headers)) {
        if (value === undefined || name.startsWith(":")) continue;
        headers.set(name, Array.isArray(value) ? value.join(", ") : value);
      }
      const origin = `http://${req.headers.host || `${host}:${port}`}`;
      let request;
      try {
        request = new Request(new URL(req.url || "/", origin), {
          method: req.method,
          headers,
        });
      } catch {
        res.writeHead(400, { "content-type": "text/plain; charset=utf-8" });
        res.end("bad request\n");
        status = 400;
        return;
      }
      const response = await handler(request);
      status = response.status;
      rpc = response.headers.get("x-quay-rpc") || "";
      const out = {};
      response.headers.forEach((value, name) => {
        out[name] = value;
      });
      res.writeHead(response.status, out);
      if (response.body && req.method !== "HEAD") {
        const reader = response.body.getReader();
        res.on("close", () => reader.cancel().catch(() => {}));
        for (;;) {
          const { done, value } = await reader.read();
          if (done || res.destroyed) break;
          if (!res.write(value)) await once(res, "drain");
        }
      }
      res.end();
    } catch (error) {
      if (!res.headersSent) {
        res.writeHead(500, { "content-type": "text/plain; charset=utf-8" });
        res.end(`gateway error: ${error?.message ?? error}\n`);
      } else res.destroy();
    } finally {
      log?.(
        `${req.method} ${req.url} ${status} ${Date.now() - started} ms${rpc ? ` ${new URL(rpc).host}` : ""}`,
      );
    }
  });
  return new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(port, host, () => {
      server.off("error", reject);
      const address = server.address();
      resolve({
        server,
        host,
        port: typeof address === "object" && address ? address.port : port,
        close: () =>
          new Promise((done) => {
            server.close(() => done());
            server.closeAllConnections?.();
          }),
      });
    });
  });
}

// "0.0.0.0" and "::" listen everywhere but are not URLs a browser opens.
export function localUrl(host, port) {
  const shown =
    host === "0.0.0.0" || host === "::"
      ? "127.0.0.1"
      : host.includes(":")
        ? `[${host}]`
        : host;
  return `http://${shown}:${port}/`;
}
